
$Global:OrcaTexteEN = New-Object 'System.Collections.Generic.Dictionary[string,string]'
$t = $Global:OrcaTexteEN
$t['Telemetrie & Diagnose'] = 'Telemetry & diagnostics'
$t['Was Windows über die Nutzung deines Rechners sammelt und an Microsoft schickt: Diagnosedaten, Fehlerberichte, Programm- und Geräteinventur, geplante Sammelaufgaben.'] = 'What Windows collects about how you use your PC and sends to Microsoft: diagnostic data, error reports, program and device inventory, scheduled collection tasks.'
$t['Werbung & Tracking'] = 'Advertising & tracking'
$t['Die Werbe-ID, mit der Apps dein Verhalten über Programme hinweg verknüpfen.'] = 'The advertising ID that apps use to link your behaviour across programs.'
$t['KI, Copilot & Recall'] = 'AI, Copilot & Recall'
$t['KI-Funktionen, die Bildschirminhalte, Texte oder Eingaben auswerten - teils lokal, teils auf Microsoft-Servern.'] = 'AI features that analyse screen content, text or input - partly on the device, partly on Microsoft servers.'
$t['Vorschläge & Sperrbildschirm'] = 'Suggestions & lock screen'
$t['Werbung, Tipps und vorgeschlagene Apps im Startmenü, in den Einstellungen und auf dem Sperrbildschirm.'] = 'Ads, tips and suggested apps in the Start menu, in Settings and on the lock screen.'
$t['Explorer'] = 'Explorer'
$t['Cloud-Inhalte und Zusatzeinträge im Datei-Explorer.'] = 'Cloud content and extra entries in File Explorer.'
$t['App-Berechtigungen'] = 'App permissions'
$t['Worauf Apps zugreifen dürfen: Kamera, Mikrofon, Standort, Kontakte, Dateien und Geräte.'] = 'What apps may access: camera, microphone, location, contacts, files and devices.'
$t['Suche'] = 'Search'
$t['Websuche, Cloud-Suche und Suchverlauf im Startmenü und in der Taskleiste.'] = 'Web search, cloud search and search history in the Start menu and taskbar.'
$t['Standort'] = 'Location'
$t['Standortdienste, Sensoren und "Mein Gerät suchen".'] = 'Location services, sensors and "Find my device".'
$t['Eingabe, Sprache & Zwischenablage'] = 'Input, speech & clipboard'
$t['Was Windows aus Tastatur, Stift, Sprache und Zwischenablage lernt oder in die Cloud schickt.'] = 'What Windows learns from keyboard, pen, speech and clipboard or sends to the cloud.'
$t['Updates & Übermittlung'] = 'Updates & delivery'
$t['Wie Updates auf den Rechner kommen und mit wem er sie teilt.'] = 'How updates reach the PC and who it shares them with.'
$t['Konto, OneDrive & Mobilgeräte'] = 'Account, OneDrive & mobile devices'
$t['Microsoft-Konto, Synchronisierung, OneDrive und verbundene Smartphones.'] = 'Microsoft account, sync, OneDrive and connected phones.'
$t['Microsoft Office'] = 'Microsoft Office'
$t['Telemetrie, Cloud-Funktionen und Werbung in Word, Excel, Outlook und Co.'] = 'Telemetry, cloud features and ads in Word, Excel, Outlook and co.'
$t['Edge'] = 'Edge'
$t['Datenschutzvorgaben für den Edge-Browser. Wirken nur, wenn Edge installiert ist.'] = 'Privacy policies for the Edge browser. Only take effect if Edge is installed.'
$t['Defender'] = 'Defender'
$t['Was der Virenschutz an Microsoft meldet - und zusätzlicher Schutz vor unerwünschter Software. Einzelne Schutzfunktionen lassen sich auf Wunsch abschalten; jede davon ist als Sicherheitsrisiko gekennzeichnet.'] = 'What the antivirus reports to Microsoft - and extra protection against unwanted software. Individual protection features can be switched off on request; each of them is marked as a security risk.'
$t['Gaming'] = 'Gaming'
$t['Spielaufzeichnung im Hintergrund und Game Bar.'] = 'Background game recording and Game Bar.'
$t['Netzwerk & Fernzugriff'] = 'Network & remote access'
$t['Fernzugriff, DNS, Gerätekennung, Hosts-Sperren und Verbindungsprüfungen.'] = 'Remote access, DNS, device ID, hosts blocking and connectivity checks.'
$t['Sicherheit'] = 'Security'
$t['Veraltete Netzwerkprotokolle, Anmeldesicherheit und Autostart von Datenträgern.'] = 'Outdated network protocols, sign-in security and autorun of drives.'
$t['Spuren'] = 'Traces'
$t['Was auf dem Datenträger an Kopien und Resten liegen bleibt.'] = 'Copies and leftovers that remain on the disk.'
$t['Leistung (VBS)'] = 'Performance (VBS)'
$t['Virtualisierungsbasierte Sicherheit: kostet Leistung, schützt erst, wenn ein Angreifer schon Administrator ist.'] = 'Virtualization-based security: costs performance and only protects once an attacker is already an administrator.'
$t['Experimentell'] = 'Experimental'
$t['Einstellungen, die den Rechner schneller machen sollen - zum Ausprobieren, jede mit klarer Einstufung.'] = 'Settings meant to make the PC faster - to try out, each with a clear rating.'
$t['Einstellungen'] = 'Settings'
$t['Prüft alle aktiven Punkte und stellt zurück, was Windows oder ein Programm verstellt hat.'] = 'Checks all active items and restores anything Windows or a program has changed.'
$t['Entfernte Apps'] = 'Removed apps'
$t['Erkennt entfernte Apps, die ein Update zurückgebracht hat, und entfernt sie erneut.'] = 'Detects removed apps that an update brought back and removes them again.'
$t['Defender und Firewall'] = 'Defender and firewall'
$t['Meldet abgeschaltete Schutzfunktionen, neue Ausnahmen und neue Virenfunde.'] = 'Reports disabled protection features, new exclusions and new detections.'
$t['Gerätekennung'] = 'Device ID'
$t['Meldet eine gespeicherte Microsoft-Gerätekennung, solange deren Sperre aktiv ist.'] = 'Reports a stored Microsoft device ID as long as its block is active.'
$t['Herunterfahren-Wächter'] = 'Shutdown watcher'
$t['Prüft, ob die Bereinigung beim Herunterfahren eingetragen ist und zuletzt lief, und trägt sie bei Bedarf neu ein.'] = 'Checks whether the shutdown cleanup is registered and ran last time, and registers it again if needed.'
$t['TRIM nach der Bereinigung'] = 'TRIM after cleanup'
$t['Schickt nach einer Bereinigung einen TRIM-Durchlauf an die SSD, damit gelöschte Daten wirklich weg sind.'] = 'Sends a TRIM pass to the SSD after a cleanup so deleted data is really gone.'
$t['Schreibrechte'] = 'Write permissions'
$t['Prüft, dass nur Administratoren und SYSTEM die OrcaShield-Dateien ändern dürfen, und korrigiert das.'] = 'Checks that only administrators and SYSTEM can change the OrcaShield files, and corrects it.'
$t['Hypervisor'] = 'Hypervisor'
$t['Meldet, wenn der Hypervisor trotz Abschaltung läuft.'] = 'Reports when the hypervisor is running despite being switched off.'
$t['Suchindex'] = 'Search index'
$t['Meldet Laufwerke im Suchindex, die dort nicht hingehören.'] = 'Reports drives in the search index that do not belong there.'
$t['Autostart'] = 'Autostart'
$t['Meldet neue Autostart-Einträge: Run-Schlüssel, Autostart-Ordner und Aufgaben, die bei Anmeldung oder Start laufen.'] = 'Reports new autostart entries: Run keys, startup folders and tasks that run at sign-in or boot.'
$t['Fremde Richtlinien'] = 'Foreign policies'
$t['Meldet neue oder geänderte Richtlinien, die nicht von OrcaShield stammen.'] = 'Reports new or changed policies that do not come from OrcaShield.'
$t['Stammzertifikate'] = 'Root certificates'
$t['Meldet neue Stammzertifikate. Mit einem fremden Stammzertifikat lassen sich verschlüsselte Verbindungen mitlesen.'] = 'Reports new root certificates. A foreign root certificate allows encrypted connections to be read.'
$t['Proxy'] = 'Proxy'
$t['Meldet, wenn ein Proxy eingetragen oder geändert wurde - für dein Konto, für das System oder als Umgebungsvariable.'] = 'Reports when a proxy was set or changed - for your account, for the system or as an environment variable.'
$t['Firewall eingehend'] = 'Inbound firewall'
$t['Meldet neue Firewallregeln, die eingehende Verbindungen erlauben.'] = 'Reports new firewall rules that allow inbound connections.'
$t['Neue Telemetrie'] = 'New telemetry'
$t['Meldet Aufgaben und Dienste mit den Namen bekannter Sammler, die neu dazugekommen sind und noch nicht in OrcaShield stehen.'] = 'Reports tasks and services named like known collectors that are new and not yet in OrcaShield.'
$t['Bericht nach Update'] = 'Report after update'
$t['Hält nach einem Funktionsupdate fest, was das Update verstellt hat und was neu dazugekommen ist.'] = 'After a feature update, records what the update changed and what was added.'
$t['Diagnosedaten auf Minimum (ohne Sperre)'] = 'Diagnostic data to minimum (no lock)'
$t['Setzt die Übermittlung von Diagnosedaten auf "nur erforderlich". Windows sendet dann keine optionalen Nutzungs- und Absturzdaten mehr. Der Schalter unter Datenschutz, Diagnose und Feedback bleibt bedienbar - stellst du ihn zwischendurch um, setzt der Wächter ihn beim nächsten Start zurück.'] = 'Sets diagnostic data to "required only". Windows then no longer sends optional usage and crash data. The switch under Privacy, Diagnostics & feedback stays usable - if you change it in between, the watcher resets it at the next start.'
$t['Dies ist der Ort, an den die Einstellungen-App selbst schreibt. Microsoft dokumentiert ihn nicht ausdrücklich - er sperrt dafür nichts. Wer die Sperre in Kauf nimmt, nimmt stattdessen TEL001.'] = 'This is the place the Settings app itself writes to. Microsoft does not document it explicitly - in return it locks nothing. If you accept the lock, use TEL001 instead.'
$t['Diagnosedaten per Richtlinie erzwingen'] = 'Enforce diagnostic data by policy'
$t['Erzwingt die niedrigste Diagnosestufe über die Gruppenrichtlinie, sodass sie sich auch von einem anderen Konto aus nicht mehr anheben lässt. Für dein eigenes Konto genügt der vorige Punkt - dieser hier lohnt sich nur, wenn weitere Konten auf dem Rechner existieren.'] = 'Enforces the lowest diagnostic level via Group Policy so it cannot be raised from another account either. For your own account the previous item is enough - this one is only worthwhile if there are other accounts on the PC.'
$t['Der Schalter unter Einstellungen, Datenschutz und Sicherheit, Diagnose und Feedback wird danach gesperrt und zeigt "Einige Einstellungen werden von Ihrer Organisation verwaltet". WICHTIG: Microsoft setzt den Wert 0 nur auf Enterprise, Education und Server um - auf Pro und Home behandelt Windows ihn wie 1. Du bekommst hier also dasselbe Ergebnis wie beim vorigen Punkt und bezahlst es mit der Sperre. Zusätzlich lässt sich das Windows-Insider-Programm mit gesetzter Richtlinie nicht mehr nutzen.'] = 'The switch under Settings, Privacy & security, Diagnostics & feedback is then locked and shows "Some settings are managed by your organization". IMPORTANT: Microsoft only honours the value 0 on Enterprise, Education and Server - on Pro and Home Windows treats it like 1. So you get the same result as with the previous item and pay for it with the lock. In addition, the Windows Insider Program can no longer be used while the policy is set.'
$t['Gerätenamen nicht mitübertragen'] = 'Do not send the device name'
$t['Seit Windows 10 1803 wird der Name deines Rechners zusammen mit den Diagnosedaten übertragen. Das ist der unmittelbarste Personenbezug im ganzen Telemetriepaket, weil Gerätenamen oft den echten Namen enthalten. Dieser Punkt unterbindet das.'] = 'Since Windows 10 1803 the name of your PC is sent along with the diagnostic data. That is the most direct personal reference in the whole telemetry package, because device names often contain the real name. This item stops it.'
$t['Keine zusätzlichen Diagnoseprotokolle'] = 'No additional diagnostic logs'
$t['Verhindert, dass Microsoft über die Diagnoseschnittstelle zusätzliche Protokolldateien von deinem Rechner nachfordert.'] = 'Prevents Microsoft from requesting additional log files from your PC via the diagnostics interface.'
$t['Keine Speicherabbilder übermitteln'] = 'Do not send memory dumps'
$t['Verhindert die Übermittlung von Speicherabbildern. Solche Abbilder können Ausschnitte des Arbeitsspeichers und damit auch entschlüsselte Inhalte enthalten.'] = 'Prevents memory dumps from being sent. Such dumps can contain parts of the working memory and therefore also decrypted content.'
$t['OneSettings-Abrufe unterbinden'] = 'Stop OneSettings downloads'
$t['Windows holt sich laufend Konfigurationsdaten vom Microsoft-Dienst OneSettings - ein Kanal, der in beide Richtungen arbeitet und über den Funktionen stillschweigend ein- und ausgeschaltet werden. Dieser Punkt schließt ihn.'] = 'Windows constantly fetches configuration data from the Microsoft service OneSettings - a channel that works in both directions and through which features are silently switched on and off. This item closes it.'
$t['Dienst DiagTrack deaktivieren'] = 'Disable the DiagTrack service'
$t['Stoppt den Dienst "Connected User Experiences and Telemetry" (DiagTrack). Das ist der Hauptkanal, über den Windows Nutzungs- und Diagnosedaten sammelt und versendet. Spart zusätzlich Arbeitsspeicher und CPU-Last im Hintergrund.'] = 'Stops the "Connected User Experiences and Telemetry" service (DiagTrack). It is the main channel through which Windows collects and sends usage and diagnostic data. Also saves memory and background CPU load.'
$t['Dienst dmwappushservice deaktivieren'] = 'Disable the dmwappushservice service'
$t['Deaktiviert den WAP-Push-Nachrichtenrouting-Dienst, der als zweiter Telemetriekanal genutzt wird. Wird auf einem privaten Rechner ohne Geräteverwaltung nicht benötigt.'] = 'Disables the WAP push message routing service, which is used as a second telemetry channel. Not needed on a private PC without device management.'
$t['Angepasste Erlebnisse abschalten'] = 'Turn off tailored experiences'
$t['Verhindert, dass Windows die gesammelten Diagnosedaten nutzt, um personalisierte Tipps, Werbung und Empfehlungen anzuzeigen. Der Schalter in den Einstellungen bleibt bedienbar.'] = 'Prevents Windows from using the collected diagnostic data to show personalised tips, ads and recommendations. The switch in Settings stays usable.'
$t['Fehlerberichterstattung deaktivieren'] = 'Disable error reporting'
$t['Schaltet die Windows-Fehlerberichterstattung (WER) ab. Bei Programmabstürzen werden dann keine Absturzberichte samt Speicherausschnitten mehr an Microsoft gesendet. Nachteil: Microsoft erfährt nichts von Fehlern, die dich betreffen - für die Fehlersuche auf dem eigenen Rechner ändert sich nichts, lokale Ereignisprotokolle bleiben erhalten.'] = 'Turns off Windows Error Reporting (WER). Crash reports including memory excerpts are then no longer sent to Microsoft when programs crash. Downside: Microsoft learns nothing about errors that affect you - troubleshooting on your own PC is unchanged, local event logs remain.'
$t['Telemetrie-Datensammler (Autologger)'] = 'Telemetry data collector (autologger)'
$t['Schaltet den Ereignissammler ab, der die Telemetriedaten überhaupt erst einsammelt. Das ist die Ebene UNTER dem Dienst DiagTrack: Selbst wenn Microsoft den Dienst per Update wieder einschaltet, bekommt er nichts mehr zu sehen. Für den Dauerschutz die wirksamste Einzelmaßnahme im ganzen Katalog. Kein sichtbarer Schalter betroffen.'] = 'Turns off the event collector that gathers the telemetry data in the first place. This is the layer BELOW the DiagTrack service: even if Microsoft re-enables the service with an update, it gets nothing to see. For lasting protection the most effective single measure in the whole catalogue. No visible switch affected.'
$t['CEIP-Datensammler (SQMLogger)'] = 'CEIP data collector (SQMLogger)'
$t['Schaltet den zweiten Ereignissammler ab, der Daten für das Programm zur Verbesserung der Benutzerfreundlichkeit aufzeichnet. Auf neueren Windows-Versionen gibt es diesen Sammler nicht mehr - dann wird der Punkt übersprungen statt einen Schlüssel anzulegen, den Windows nie hatte.'] = 'Turns off the second event collector, which records data for the Customer Experience Improvement Program. Newer Windows versions no longer have this collector - the item is then skipped instead of creating a key Windows never had.'
$t['CEIP systemweit abschalten'] = 'Turn off CEIP system-wide'
$t['Schaltet die Teilnahme am Programm zur Verbesserung der Benutzerfreundlichkeit für den gesamten Rechner ab.'] = 'Turns off participation in the Customer Experience Improvement Program for the whole PC.'
$t['Feedback-Anfragen unterbinden'] = 'Stop feedback requests'
$t['Setzt die Häufigkeit der Windows-Feedback-Anfragen auf null. Die Einblendungen "Wie zufrieden sind Sie mit ..." bleiben danach aus.'] = 'Sets the frequency of Windows feedback requests to zero. The "How satisfied are you with ..." prompts no longer appear.'
$t['Feedback-Benachrichtigungen aus'] = 'Feedback notifications off'
$t['Unterbindet zusätzlich die Benachrichtigungen, mit denen Windows zur Rückmeldung auffordert.'] = 'Additionally stops the notifications with which Windows asks for feedback.'
$t['CEIP-Aufgabe: Consolidator'] = 'CEIP task: Consolidator'
$t['Deaktiviert die geplante Aufgabe des Programms zur Verbesserung der Benutzerfreundlichkeit. Diese Aufgabe sammelt periodisch Nutzungsdaten und sendet sie an Microsoft.'] = 'Disables the scheduled task of the Customer Experience Improvement Program. This task periodically collects usage data and sends it to Microsoft.'
$t['CEIP-Aufgabe: UsbCeip'] = 'CEIP task: UsbCeip'
$t['Deaktiviert die Erfassung von Daten über angeschlossene USB-Geräte.'] = 'Disables the collection of data about connected USB devices.'
$t['Kernel-CEIP-Aufgabe'] = 'Kernel CEIP task'
$t['Deaktiviert die Erfassung von Kernel-Nutzungsdaten für das CEIP. Auf neueren Windows-Versionen nicht mehr vorhanden.'] = 'Disables the collection of kernel usage data for CEIP. No longer present on newer Windows versions.'
$t['CEIP-Aufgabe: PI Sqm-Tasks'] = 'CEIP task: PI Sqm tasks'
$t['Deaktiviert einen weiteren Sammler des Programms zur Verbesserung der Benutzerfreundlichkeit.'] = 'Disables another collector of the Customer Experience Improvement Program.'
$t['Kompatibilitäts-Scan (Appraiser)'] = 'Compatibility scan (Appraiser)'
$t['Deaktiviert den Microsoft Compatibility Appraiser. Diese Aufgabe scannt regelmäßig deine installierte Software und Hardware und überträgt ein detailliertes Systemverzeichnis an Microsoft. Spart zusätzlich spürbar Festplattenaktivität im Hintergrund.'] = 'Disables the Microsoft Compatibility Appraiser. This task regularly scans your installed software and hardware and sends a detailed system inventory to Microsoft. Also saves noticeable disk activity in the background.'
$t['Programmdaten-Updater'] = 'Program data updater'
$t['Deaktiviert die Aufgabe ProgramDataUpdater, die Anwendungs-Telemetrie für den Kompatibilitäts-Assistenten aufbereitet.'] = 'Disables the ProgramDataUpdater task, which prepares application telemetry for the compatibility assistant.'
$t['Anwendungstelemetrie (AitAgent)'] = 'Application telemetry (AitAgent)'
$t['Deaktiviert den Agenten, der Anwendungsnutzung für den Kompatibilitäts-Assistenten protokolliert. Auf Windows 11 in der Regel nicht mehr vorhanden.'] = 'Disables the agent that logs application usage for the compatibility assistant. Usually no longer present on Windows 11.'
$t['Autostart-Analyse (StartupAppTask)'] = 'Autostart analysis (StartupAppTask)'
$t['Deaktiviert die Aufgabe, die deine Autostart-Programme erfasst und bewertet.'] = 'Disables the task that records and rates your autostart programs.'
$t['Kompatibilitäts-Scan, Expressfassung'] = 'Compatibility scan, express version'
$t['Deaktiviert die Aufgabe "Microsoft Compatibility Appraiser Exp". Laut eigener Beschreibung sammelt sie Programmtelemetrie; sie startet compattelrunner.exe mit dem Appraiser im Expressmodus - dieselbe Bestandsaufnahme wie der Kompatibilitäts-Scan weiter oben, nur über einen eigenen Auslöser.'] = 'Disables the task "Microsoft Compatibility Appraiser Exp". According to its own description it collects program telemetry; it starts compattelrunner.exe with the Appraiser in express mode - the same inventory as the compatibility scan above, just with its own trigger.'
$t['Kompatibilitäts-Aufgabe (MareBackup)'] = 'Compatibility task (MareBackup)'
$t['Deaktiviert eine weitere in Windows 11 hinzugekommene Aufgabe der Kompatibilitäts-Telemetrie.'] = 'Disables another compatibility telemetry task added in Windows 11.'
$t['Geräteinventur (Device Census)'] = 'Device inventory (Device Census)'
$t['Deaktiviert die Gerätevolkszählung. Sie erstellt eine vollständige Aufstellung deiner Hardware und der installierten Software und überträgt sie an Microsoft. Von allen geplanten Aufgaben die mit dem größten Datenumfang.'] = 'Disables the device census. It creates a complete list of your hardware and installed software and sends it to Microsoft. Of all scheduled tasks the one with the largest amount of data.'
$t['Geräteinventur, benutzerbezogen'] = 'Device inventory, per user'
$t['Das benutzerbezogene Gegenstück zur Geräteinventur.'] = 'The per-user counterpart to the device inventory.'
$t['Nutzungsdaten der Funktionsausrollung'] = 'Feature rollout usage data'
$t['Deaktiviert die Übermittlung von Nutzungsdaten, mit denen Microsoft die schrittweise Ausrollung neuer Funktionen steuert.'] = 'Disables sending usage data that Microsoft uses to steer the gradual rollout of new features.'
$t['OneSettings-Abruf (Aufgabe)'] = 'OneSettings download (task)'
$t['Deaktiviert die Aufgabe, die die OneSettings-Konfiguration von Microsoft holt. Gegenstück zum Registrypunkt weiter oben.'] = 'Disables the task that fetches the OneSettings configuration from Microsoft. Counterpart to the registry item above.'
$t['Feedback-Aufgabe DmClient'] = 'Feedback task DmClient'
$t['Deaktiviert die geplante Aufgabe, die Feedback-Kampagnen abruft.'] = 'Disables the scheduled task that fetches feedback campaigns.'
$t['Feedback-Aufgabe DmClientOnScenarioDownload'] = 'Feedback task DmClientOnScenarioDownload'
$t['Deaktiviert die zugehörige Nachladeaufgabe für Feedback-Szenarien.'] = 'Disables the related download task for feedback scenarios.'
$t['Datentraeger-Diagnosedaten'] = 'Disk diagnostic data'
$t['Deaktiviert die Aufgabe, die Datenträgerzustandsdaten sammelt und übermittelt.'] = 'Disables the task that collects and sends disk health data.'
$t['Speicherplatz-Analyse (DiskFootprint)'] = 'Storage analysis (DiskFootprint)'
$t['Deaktiviert die Aufgabe, die eine Aufstellung deiner Speicherplatzbelegung erstellt.'] = 'Disables the task that creates a breakdown of your storage usage.'
$t['Fehlerbericht-Warteschlange'] = 'Error report queue'
$t['Deaktiviert die Aufgabe, die gesammelte Fehlerberichte nachträglich an Microsoft überträgt.'] = 'Disables the task that sends collected error reports to Microsoft later.'
$t['Autochk-Proxy-Aufgabe'] = 'Autochk proxy task'
$t['Deaktiviert eine Aufgabe, die Daten der Datenträgerprüfung an das CEIP weiterreicht.'] = 'Disables a task that passes disk check data on to CEIP.'
$t['Handschriftdaten nicht weitergeben'] = 'Do not share handwriting data'
$t['Verhindert, dass Windows Proben deiner Handschrift an Microsoft schickt, um die Handschrifterkennung zu verbessern. Betrifft Stift- und Toucheingabe; ohne Stift ändert sich nichts.'] = 'Prevents Windows from sending samples of your handwriting to Microsoft to improve handwriting recognition. Affects pen and touch input; without a pen nothing changes.'
$t['Keine Fehlerberichte der Handschrifterkennung'] = 'No handwriting recognition error reports'
$t['Verhindert Fehlerberichte der Handschrifterkennung an Microsoft. Solche Berichte können Ausschnitte des Geschriebenen enthalten.'] = 'Prevents handwriting recognition error reports to Microsoft. Such reports can contain excerpts of what was written.'
$t['Programminventur abschalten (Inventory Collector)'] = 'Turn off program inventory (Inventory Collector)'
$t['Schaltet den Inventory Collector ab. Er listet installierte Programme, Dateien und Geräte auf und überträgt die Liste an Microsoft. Die Kompatibilitätshilfe für alte Programme bleibt erhalten.'] = 'Turns off the Inventory Collector. It lists installed programs, files and devices and sends the list to Microsoft. The compatibility help for old programs remains.'
$t['Anwendungstelemetrie abschalten'] = 'Turn off application telemetry'
$t['Schaltet die Anwendungstelemetrie ab, die festhält, wie Programme Windows-Funktionen nutzen, und sie an Microsoft meldet. Ergänzt die Aufgabe AitAgent (TEL018) um den Schalter selbst.'] = 'Turns off application telemetry, which records how programs use Windows features and reports it to Microsoft. Adds the switch itself to the AitAgent task (TEL018).'
$t['Schrittaufzeichnung abschalten'] = 'Turn off Steps Recorder'
$t['Schaltet die Schrittaufzeichnung ab, die Klicks und Bildschirmfotos für Fehlerberichte mitschneidet. Ab Windows 11 24H2 ist das Programm ohnehin entfallen - der Punkt sorgt dafür, dass es auch über Umwege nicht anspringt.'] = 'Turns off the Steps Recorder, which captures clicks and screenshots for error reports. The program is gone anyway as of Windows 11 24H2 - this item makes sure it cannot start through a back door.'
$t['Angepasste Erlebnisse per Richtlinie sperren'] = 'Lock tailored experiences by policy'
$t['Verbietet über die Richtlinie, dass Windows Diagnosedaten für personalisierte Tipps und Werbung nutzt. TEL004 erledigt dasselbe ohne Sperre.'] = 'Forbids by policy that Windows uses diagnostic data for personalised tips and ads. TEL004 does the same without a lock.'
$t['Der Schalter "Angepasste Benutzererfahrungen" unter Datenschutz, Diagnose und Feedback wird gesperrt.'] = 'The switch "Tailored experiences" under Privacy, Diagnostics & feedback is locked.'
$t['Keine Auswertung für Desktop Analytics'] = 'No processing for Desktop Analytics'
$t['Verbietet, dass Diagnosedaten dieses Rechners für den Unternehmensdienst Desktop Analytics verarbeitet werden.'] = 'Forbids processing of this PC''s diagnostic data for the business service Desktop Analytics.'
$t['Keine Cloud-Auswertung für Windows Update for Business'] = 'No cloud processing for Windows Update for Business'
$t['Verbietet die Cloud-Verarbeitung von Diagnosedaten für die Unternehmensverwaltung von Updates.'] = 'Forbids cloud processing of diagnostic data for business update management.'
$t['Keine Auswertung für Update Compliance'] = 'No processing for Update Compliance'
$t['Verbietet, dass Diagnosedaten für den Dienst Update Compliance verarbeitet werden.'] = 'Forbids processing of diagnostic data for the Update Compliance service.'
$t['Keine geschäftliche Datenverarbeitung'] = 'No commercial data processing'
$t['Verbietet, dass Microsoft gesammelte Diagnosedaten in der geschäftlichen Datenpipeline weiterverarbeitet.'] = 'Forbids Microsoft from processing collected diagnostic data in its commercial data pipeline.'
$t['Fehlerberichte: keine Zusatzdaten'] = 'Error reports: no additional data'
$t['Falls doch ein Fehlerbericht entsteht, werden keine zusätzlichen Daten (etwa Speicherausschnitte) mitgeschickt.'] = 'If an error report is created anyway, no additional data (such as memory excerpts) is sent with it.'
$t['Fehlerberichte: auch lokal nicht protokollieren'] = 'Error reports: do not log locally either'
$t['Die Fehlerberichterstattung schreibt auch keine lokalen Einträge mehr.'] = 'Error reporting no longer writes local entries either.'
$t['Abstürze erscheinen dann nicht mehr im Zuverlässigkeitsverlauf - das erschwert die eigene Fehlersuche.'] = 'Crashes then no longer appear in the reliability history - this makes your own troubleshooting harder.'
$t['Fehlerberichte: vor dem Senden immer fragen'] = 'Error reports: always ask before sending'
$t['Legt fest, dass Windows vor jedem Fehlerbericht nachfragt, statt Daten selbsttätig zu senden.'] = 'Makes Windows ask before every error report instead of sending data on its own.'
$t['Aufgabe: Datenträgerdiagnose-Meldungen'] = 'Task: disk diagnostic messages'
$t['Deaktiviert die Aufgabe, die Ergebnisse der Datenträgerdiagnose auswertet und meldet.'] = 'Disables the task that evaluates and reports disk diagnostic results.'
$t['Dienst: Windows-Fehlerberichterstattung'] = 'Service: Windows Error Reporting'
$t['Deaktiviert den Dienst der Fehlerberichterstattung. Ergänzt TEL005: Selbst wenn die Richtlinie umgangen wird, läuft nichts.'] = 'Disables the error reporting service. Adds to TEL005: even if the policy is bypassed, nothing runs.'
$t['Programme, die eigene Absturzberichte über Windows verschicken, können das nicht mehr.'] = 'Programs that send their own crash reports through Windows can no longer do so.'
$t['Dienst: Fehlerbericht-Systemsteuerung'] = 'Service: Problem Reports control panel'
$t['Deaktiviert den Dienst, der Lösungen zu Fehlerberichten in der Systemsteuerung anzeigt.'] = 'Disables the service that shows solutions for error reports in the Control Panel.'
$t['Dienst: Diagnoseausführung'] = 'Service: Diagnostic Execution'
$t['Deaktiviert den Dienst, mit dem Microsoft Diagnosen auf dem Rechner ausführen lässt.'] = 'Disables the service through which Microsoft can run diagnostics on the PC.'
$t['Die Problembehandlungen von Windows (etwa für Netzwerk und Audio) funktionieren danach teilweise nicht mehr.'] = 'Some Windows troubleshooters (for example for network and audio) then no longer fully work.'
$t['Dienst: Diagnose-Hub-Sammler'] = 'Service: Diagnostics Hub collector'
$t['Deaktiviert den Sammeldienst des Diagnose-Hubs (Leistungs- und Ablaufdaten). Fehlt er, wird nichts angelegt.'] = 'Disables the collector service of the Diagnostics Hub (performance and trace data). If it is missing, nothing is created.'
$t['Entwicklungswerkzeuge wie Visual Studio können danach keine Leistungsmessungen mehr aufzeichnen.'] = 'Development tools such as Visual Studio can then no longer record performance measurements.'
$t['Programmkompatibilitäts-Assistent aus'] = 'Program Compatibility Assistant off'
$t['Schaltet den Assistenten ab, der nach dem Start alter Programme Kompatibilitätsprobleme erkennt und Daten dazu sammelt.'] = 'Turns off the assistant that detects compatibility problems after old programs start and collects data about them.'
$t['Ältere Programme und Spiele bekommen keine automatischen Kompatibilitätshilfen mehr.'] = 'Older programs and games no longer get automatic compatibility help.'
$t['Kompatibilitäts-Engine aus'] = 'Compatibility engine off'
$t['Schaltet die Engine ab, die alten Programmen beim Start Kompatibilitätskorrekturen unterschiebt und dafür jeden Programmstart prüft.'] = 'Turns off the engine that applies compatibility fixes to old programs at start and checks every program start for that.'
$t['Manche älteren Programme und Installationsprogramme starten danach nicht mehr oder verhalten sich fehlerhaft.'] = 'Some older programs and installers may then no longer start or may misbehave.'
$t['Reiter "Kompatibilität" ausblenden'] = 'Hide the "Compatibility" tab'
$t['Blendet in den Eigenschaften von Programmdateien den Reiter "Kompatibilität" aus.'] = 'Hides the "Compatibility" tab in the properties of program files.'
$t['Kompatibilitätsmodus und Ausführen als Administrator lassen sich dann nicht mehr über diesen Reiter einstellen.'] = 'Compatibility mode and Run as administrator can then no longer be set through this tab.'
$t['Media Player: keine CD- und DVD-Informationen abrufen'] = 'Media Player: do not fetch CD and DVD information'
$t['Der klassische Windows Media Player fragt zu eingelegten CDs und DVDs keine Titel- und Albuminformationen mehr im Netz ab.'] = 'The classic Windows Media Player no longer looks up title and album information for inserted CDs and DVDs online.'
$t['Media Player: keine Informationen zu Musikdateien abrufen'] = 'Media Player: do not fetch music file information'
$t['Der klassische Windows Media Player ergänzt fehlende Angaben zu Musikdateien nicht mehr aus dem Netz.'] = 'The classic Windows Media Player no longer completes missing music file details from the internet.'
$t['Werbe-ID deaktivieren'] = 'Turn off the advertising ID'
$t['Schaltet die geräteweite Werbe-ID ab, mit der Apps dein Nutzungsverhalten über verschiedene Anwendungen hinweg verknüpfen können. Apps zeigen danach unpersonalisierte statt personalisierter Werbung. Der Schalter in den Einstellungen bleibt bedienbar.'] = 'Turns off the device-wide advertising ID that apps can use to link your usage across applications. Apps then show non-personalised instead of personalised ads. The switch in Settings stays usable.'
$t['Werbe-ID für ALLE Konten sperren'] = 'Lock the advertising ID for ALL accounts'
$t['Sperrt die Werbe-ID zusätzlich für alle Benutzerkonten des Rechners, auch für künftig angelegte. Für dein eigenes Konto genügt bereits der vorige Punkt - dieser hier lohnt sich nur, wenn weitere Konten auf dem Rechner existieren.'] = 'Additionally locks the advertising ID for all user accounts on the PC, including ones created later. For your own account the previous item is already enough - this one is only worthwhile if there are other accounts on the PC.'
$t['Der Schalter unter Einstellungen, Datenschutz und Sicherheit, Allgemein, "Apps das Anzeigen personalisierter Werbung erlauben" wird danach gesperrt. Wenn dir dein eigenes Konto genügt, antworte hier mit Nein - der vorige Punkt erledigt das bereits ohne Sperre.'] = 'The switch under Settings, Privacy & security, General, "Let apps show me personalized ads" is then locked. If your own account is enough, answer No here - the previous item already does this without a lock.'
$t['Windows Copilot deaktivieren'] = 'Disable Windows Copilot'
$t['Schaltet den KI-Assistenten Copilot über die Richtlinie ab. Eingaben an Copilot werden andernfalls zur Verarbeitung an Microsoft-Server gesendet.'] = 'Turns off the AI assistant Copilot via policy. Otherwise input to Copilot is sent to Microsoft servers for processing.'
$t['Microsoft führt diese Richtlinie inzwischen als veraltet: Sie steuert die ältere, in Windows eingebettete Copilot-Oberfläche. Der heutige Copilot ist eine eigene App - sie wird über die App-Entfernung losgeworden (Eintrag S14), und das Symbol blendet der nächste Punkt aus.'] = 'Microsoft now lists this policy as deprecated: it controls the older Copilot interface embedded in Windows. Today''s Copilot is a separate app - it is removed via app removal (entry S14), and the next item hides the icon.'
$t['Copilot-Symbol ausblenden'] = 'Hide the Copilot icon'
$t['Entfernt die Copilot-Schaltfläche aus der Taskleiste. Der Schalter unter Personalisierung, Taskleiste bleibt bedienbar.'] = 'Removes the Copilot button from the taskbar. The switch under Personalization, Taskbar stays usable.'
$t['Recall deaktivieren'] = 'Disable Recall'
$t['Verhindert, dass Windows fortlaufend Bildschirmaufnahmen anfertigt und durchsuchbar speichert. Recall ist eine der weitreichendsten Datensammelfunktionen überhaupt, weil sie alles erfasst, was auf dem Bildschirm sichtbar war.'] = 'Prevents Windows from continuously taking screenshots and storing them in searchable form. Recall is one of the most far-reaching data collection features of all, because it captures everything that was visible on screen.'
$t['Click to Do deaktivieren'] = 'Disable Click to Do'
$t['Schaltet die KI-gestützte Bildschirmanalyse "Click to Do" ab, die Bildschirminhalte auswertet, um Kontextaktionen vorzuschlagen.'] = 'Turns off the AI screen analysis "Click to Do", which analyses screen content to suggest contextual actions.'
$t['Paint: Image Creator abschalten'] = 'Paint: turn off Image Creator'
$t['Schaltet die KI-Bilderzeugung in Paint ab, die deine Eingaben zur Verarbeitung an Microsoft-Server sendet.'] = 'Turns off AI image generation in Paint, which sends your input to Microsoft servers for processing.'
$t['Paint: Cocreator abschalten'] = 'Paint: turn off Cocreator'
$t['Schaltet den Cocreator in Paint ab, der deine Zeichnung samt Texteingabe zur Verarbeitung an Microsoft-Server sendet.'] = 'Turns off Cocreator in Paint, which sends your drawing and text prompt to Microsoft servers for processing.'
$t['Paint: Generatives Füllen abschalten'] = 'Paint: turn off generative fill'
$t['Schaltet das generative Füllen in Paint ab, bei dem Bildausschnitte zur Ergänzung an Microsoft-Server gehen.'] = 'Turns off generative fill in Paint, where parts of the image go to Microsoft servers to be completed.'
$t['Recall gar nicht erst bereitstellen'] = 'Do not provide Recall at all'
$t['Verhindert, dass Windows die Recall-Funktion überhaupt bereitstellt. Ergänzt KI003: Dort wird das Speichern von Bildschirmaufnahmen abgeschaltet, hier die Funktion selbst. Auf Rechnern ohne KI-Chip ohne sichtbare Wirkung.'] = 'Prevents Windows from providing the Recall feature at all. Adds to KI003: there saving screenshots is turned off, here the feature itself. No visible effect on PCs without an AI chip.'
$t['Einstellungs-Agent abschalten'] = 'Turn off the Settings agent'
$t['Schaltet den KI-Agenten in der Einstellungen-App ab, der Eingaben in natürlicher Sprache auswertet und Einstellungen selbst ändert. Auf Rechnern ohne KI-Chip ohne sichtbare Wirkung.'] = 'Turns off the AI agent in the Settings app, which interprets natural-language input and changes settings itself. No visible effect on PCs without an AI chip.'
$t['Editor: KI-Funktionen abschalten'] = 'Notepad: turn off AI features'
$t['Schaltet die KI-Funktionen im Windows-Editor ab (Umschreiben, Zusammenfassen). Sie schicken den markierten Text zur Verarbeitung an Microsoft-Server.'] = 'Turns off the AI features in Notepad (rewrite, summarise). They send the selected text to Microsoft servers for processing.'
$t['Bing-Chat-Berechtigung in Copilot entziehen'] = 'Remove Bing Chat eligibility in Copilot'
$t['Windows behandelt dein Konto als nicht berechtigt für den Bing-Chat in Copilot.'] = 'Windows treats your account as not eligible for Bing Chat in Copilot.'
$t['Recall auch pro Benutzer abschalten'] = 'Turn off Recall per user too'
$t['Schaltet Recall zusätzlich im Benutzerzweig ab. KI003 gilt bereits für den ganzen Rechner; dieser Punkt ist nur eine zweite Sicherung.'] = 'Additionally turns off Recall in the user branch. KI003 already applies to the whole PC; this item is only a second safeguard.'
$t['Stille App-Installationen unterbinden'] = 'Stop silent app installations'
$t['Verhindert, dass der Content Delivery Manager im Hintergrund beworbene Apps nachinstalliert. Das ist der Mechanismus, über den Spiele und Testversionen ungefragt im Startmenü auftauchen - und auf Windows 11 Pro der einzige, der ihn wirksam abstellt. Ohne diesen Punkt kehren entfernte Apps nach einem Funktionsupdate zurück.'] = 'Prevents the Content Delivery Manager from installing promoted apps in the background. This is the mechanism by which games and trials appear unasked in the Start menu - and on Windows 11 Pro the only one that effectively stops it. Without this item removed apps return after a feature update.'
$t['Vorgeschlagene Apps im Startmenü'] = 'Suggested apps in the Start menu'
$t['Verhindert, dass im Startmenü Apps vorgeschlagen werden, die du nicht installiert hast. Ergänzt den vorigen Punkt.'] = 'Prevents the Start menu from suggesting apps you have not installed. Adds to the previous item.'
$t['Sperrbildschirm-Inhalte (Spotlight)'] = 'Lock screen content (Spotlight)'
$t['Schaltet Windows-Spotlight ab. Damit lädt der Sperrbildschirm keine Bilder mehr von Microsoft-Servern. Folge: Der Sperrbildschirm zeigt stattdessen ein festes Hintergrundbild deiner Wahl.'] = 'Turns off Windows Spotlight. The lock screen then no longer loads pictures from Microsoft servers. Consequence: the lock screen shows a fixed background picture of your choice instead.'
$t['Sperrbildschirm-Einblendungen'] = 'Lock screen overlays'
$t['Schaltet zusätzlich die Textüberlagerungen und beworbenen Hinweise auf dem Sperrbildschirm ab. Ergänzt den vorigen Punkt.'] = 'Additionally turns off the text overlays and promoted hints on the lock screen. Adds to the previous item.'
$t['Sperrbildschirm: Tipps und Fakten'] = 'Lock screen: tips and facts'
$t['Verhindert die Anzeige von Tipps, Werbung und "Wusstest du schon"-Hinweisen auf dem Sperrbildschirm.'] = 'Prevents tips, ads and "Did you know" hints from being shown on the lock screen.'
$t['Tipps und Tricks Benachrichtigungen'] = 'Tips and tricks notifications'
$t['Schaltet die Benachrichtigungen "Tipps, Tricks und Vorschläge bei der Verwendung von Windows" ab. Diese Inhalte werden serverseitig ausgeliefert.'] = 'Turns off the notifications "Get tips, tricks and suggestions as you use Windows". This content is delivered from servers.'
$t['Willkommensseite nach Updates'] = 'Welcome page after updates'
$t['Verhindert die "Willkommen bei Windows"-Seite nach Funktionsupdates, die neue Microsoft-Dienste bewirbt.'] = 'Prevents the "Welcome to Windows" page after feature updates, which promotes new Microsoft services.'
$t['Vorschläge in den Einstellungen'] = 'Suggestions in Settings'
$t['Entfernt die beworbenen Empfehlungsbanner innerhalb der Einstellungen-App. Erster von drei Kanälen.'] = 'Removes the promoted recommendation banners inside the Settings app. First of three channels.'
$t['Vorschläge in den Einstellungen (zweiter Kanal)'] = 'Suggestions in Settings (second channel)'
$t['Zweiter der drei Kanäle für beworbene Empfehlungsbanner in der Einstellungen-App.'] = 'Second of the three channels for promoted recommendation banners in the Settings app.'
$t['Vorschläge in den Einstellungen (dritter Kanal)'] = 'Suggestions in Settings (third channel)'
$t['Dritter und letzter Kanal für Empfehlungsbanner in der Einstellungen-App.'] = 'Third and last channel for recommendation banners in the Settings app.'
$t['App-Vorschläge im Startmenü (zweiter Kanal)'] = 'App suggestions in the Start menu (second channel)'
$t['Schliesst den zweiten Auslieferungskanal für App-Vorschläge im Startmenü.'] = 'Closes the second delivery channel for app suggestions in the Start menu.'
$t['Weiche Landung nach Updates'] = 'Soft landing after updates'
$t['Unterbindet die Einblendungen, mit denen Windows nach Updates neue Funktionen bewirbt.'] = 'Stops the overlays with which Windows promotes new features after updates.'
$t['Empfehlungen im Startmenü (Iris)'] = 'Recommendations in the Start menu (Iris)'
$t['Entfernt den Empfehlungsbereich im unteren Teil des Startmenüs, der serverseitig befüllte Vorschläge anzeigt.'] = 'Removes the recommendation area at the bottom of the Start menu, which shows server-filled suggestions.'
$t['Kontobezogene Hinweise im Startmenü'] = 'Account-related hints in the Start menu'
$t['Schaltet die Hinweise im Startmenü ab, die zur Einrichtung von Microsoft-Diensten auffordern.'] = 'Turns off the hints in the Start menu that ask you to set up Microsoft services.'
$t['Kontobenachrichtigungen in den Einstellungen'] = 'Account notifications in Settings'
$t['Entfernt die Werbebanner für Microsoft-365-Abonnements aus der Einstellungen-App.'] = 'Removes the promotional banners for Microsoft 365 subscriptions from the Settings app.'
$t['Einrichtungsseite nach Updates (SCOOBE)'] = 'Setup page after updates (SCOOBE)'
$t['Unterbindet die ganzseitige Aufforderung "Lass uns dein Gerät vollständig einrichten", die nach größeren Updates erscheint und Microsoft-Dienste bewirbt.'] = 'Stops the full-page prompt "Let''s finish setting up your device" that appears after major updates and promotes Microsoft services.'
$t['OneDrive-Werbung im Explorer'] = 'OneDrive ads in Explorer'
$t['Entfernt die Werbeeinblendungen für OneDrive und Microsoft 365 aus dem Datei-Explorer.'] = 'Removes the promotional banners for OneDrive and Microsoft 365 from File Explorer.'
$t['Aktivitätsverlauf: Hauptschalter'] = 'Activity history: main switch'
$t['Schaltet die Aufzeichnung des Aktivitätsverlaufs insgesamt ab. Das ist der Hauptschalter der Funktion; die beiden folgenden Punkte ergänzen ihn.'] = 'Turns off recording of the activity history altogether. This is the feature''s main switch; the next two items add to it.'
$t['Aktivitätsverlauf: Veröffentlichen durch Apps'] = 'Activity history: publishing by apps'
$t['Verhindert, dass Apps ihre Aktivitäten in den Verlauf schreiben.'] = 'Prevents apps from writing their activities to the history.'
$t['Aktivitätsverlauf: Übertragung ans Konto'] = 'Activity history: upload to the account'
$t['Unterbindet die Übertragung des Aktivitätsverlaufs an dein Microsoft-Konto. Das ist der Punkt, der den Datenabfluss tatsächlich stoppt - die beiden vorigen betreffen nur die lokale Aufzeichnung.'] = 'Stops uploading the activity history to your Microsoft account. This is the item that actually stops the data flow - the previous two only concern local recording.'
$t['Zuletzt geöffnete Programme nicht merken'] = 'Do not remember recently opened programs'
$t['Verhindert, dass Windows eine Liste der zuletzt gestarteten Programme führt und im Startmenü anzeigt.'] = 'Prevents Windows from keeping a list of recently started programs and showing it in the Start menu.'
$t['Zuletzt geöffnete Dokumente nicht merken'] = 'Do not remember recently opened documents'
$t['Gegenstück zum vorigen Punkt für Dateien statt Programme: Windows führt dann keine Liste zuletzt geöffneter Dokumente mehr.'] = 'Counterpart to the previous item for files instead of programs: Windows then no longer keeps a list of recently opened documents.'
$t['Schnellzugriff: zuletzt verwendete Dateien'] = 'Quick access: recently used files'
$t['Entfernt die Liste zuletzt verwendeter Dateien aus dem Schnellzugriff des Datei-Explorers. Wer den Rechner mit anderen teilt, verrät damit nicht mehr, woran er zuletzt gearbeitet hat.'] = 'Removes the list of recently used files from Quick access in File Explorer. If you share the PC with others, it no longer reveals what you last worked on.'
$t['Schnellzugriff: häufig verwendete Ordner'] = 'Quick access: frequently used folders'
$t['Entfernt die Liste häufig verwendeter Ordner aus dem Schnellzugriff. Ergänzt den vorigen Punkt.'] = 'Removes the list of frequently used folders from Quick access. Adds to the previous item.'
$t['Wechseldatenträger im Explorer nur einmal anzeigen'] = 'Show removable drives only once in Explorer'
$t['Windows zeigt USB-Sticks und andere Wechseldatenträger im Navigationsbereich doppelt: unter "Dieser PC" und noch einmal einzeln. Das betrifft auch VeraCrypt-Laufwerke, die als Wechseldatenträger eingehängt sind. Danach erscheinen sie nur noch unter "Dieser PC". Wirkt nach der nächsten Anmeldung.'] = 'Windows shows USB sticks and other removable drives twice in the navigation pane: under "This PC" and once more on their own. This also affects VeraCrypt volumes mounted as removable drives. Afterwards they only appear under "This PC". Takes effect at the next sign-in.'
$t['Der Eintrag gehört Windows; der Rückbau legt ihn mit seinem ursprünglichen Wert wieder an.'] = 'The entry belongs to Windows; rolling back recreates it with its original value.'
$t['OneDrive nicht im Navigationsbereich'] = 'OneDrive not in the navigation pane'
$t['Blendet den Knoten "OneDrive - Personal" links im Explorer aus, der deine Ordner ein zweites Mal zeigt. OneDrive selbst funktioniert weiter, der Ordner bleibt unter deinem Benutzerordner erreichbar. Wird nur gesetzt, wenn OneDrive den Knoten angelegt hat.'] = 'Hides the "OneDrive - Personal" node on the left in Explorer, which shows your folders a second time. OneDrive itself keeps working and the folder stays reachable under your user folder. Only applied if OneDrive created the node.'
$t['Ein OneDrive-Update kann den Knoten wieder einblenden; der Wächter blendet ihn dann bei der nächsten Anmeldung wieder aus.'] = 'A OneDrive update can show the node again; the watcher then hides it again at the next sign-in.'
$t['Werbe-Nachinstallationen systemweit sperren'] = 'Block promotional reinstalls system-wide'
$t['Verhindert auf Enterprise- und Education-Systemen, dass Windows nach einem Funktionsupdate selbsttätig beworbene Apps nachinstalliert. Auf Pro und Home setzt Microsoft diese Richtlinie nicht um - dort erledigt das der Punkt "Stille App-Installationen unterbinden".'] = 'Prevents Windows on Enterprise and Education systems from installing promoted apps on its own after a feature update. Microsoft does not apply this policy on Pro and Home - there the item "Stop silent app installations" does the job.'
$t['Cloud-optimierte Inhalte sperren'] = 'Block cloud-optimised content'
$t['Schliesst den Kanal, über den Windows serverseitig ausgewählte Inhalte und Empfehlungen in die Oberfläche einspielt. Gehört zur selben Richtlinienfamilie wie der vorige Punkt und wird auf Pro und Home ebenfalls nicht durchgesetzt.'] = 'Closes the channel through which Windows feeds server-selected content and recommendations into the interface. Belongs to the same policy family as the previous item and is likewise not enforced on Pro and Home.'
$t['Sicherungs-Erinnerungen abschalten'] = 'Turn off backup reminders'
$t['Unterbindet die wiederkehrenden Aufforderungen, eine Windows-Sicherung in OneDrive einzurichten.'] = 'Stops the recurring prompts to set up a Windows backup in OneDrive.'
$t['Sprachliste nicht an Webseiten weitergeben'] = 'Do not share the language list with websites'
$t['Verhindert, dass Windows deine Liste bevorzugter Sprachen an Webseiten weiterreicht. Die Sprachliste ist ein verbreitetes Merkmal beim Wiedererkennen von Browsern. Das ist der vierte der vier Schalter unter Datenschutz, Allgemein - er bleibt bedienbar.'] = 'Prevents Windows from passing your list of preferred languages to websites. The language list is a common feature for recognising browsers. This is the fourth of the four switches under Privacy, General - it stays usable.'
$t['Kamera im Sperrbildschirm abschalten'] = 'Turn off the camera on the lock screen'
$t['Verhindert, dass sich die Kamera vom Sperrbildschirm aus starten lässt, also ohne Anmeldung. Ohne Kamera am Rechner ohne Wirkung.'] = 'Prevents the camera from being started from the lock screen, i.e. without signing in. No effect without a camera.'
$t['Hinweise zum Microsoft-Konto abschalten'] = 'Turn off Microsoft account hints'
$t['Unterbindet Inhalte, die Windows anhand deines Microsoft-Kontos einblendet (Kontostatus, Abo- und Speicherhinweise).'] = 'Stops content that Windows shows based on your Microsoft account (account status, subscription and storage hints).'
$t['Vorschläge in der Zeitachse'] = 'Suggestions in the timeline'
$t['Schaltet einen weiteren Werbe- und Vorschlagskanal des Content Delivery Managers ab, ursprünglich für die Zeitachse. Der Schalter bleibt bedienbar.'] = 'Turns off another ad and suggestion channel of the Content Delivery Manager, originally for the timeline. The switch stays usable.'
$t['Explorer: keine Dateien von office.com'] = 'Explorer: no files from office.com'
$t['Die Startseite des Explorers zeigt keine zuletzt verwendeten Dateien aus der Microsoft-Cloud (office.com, OneDrive) mehr; Windows fragt sie dafür nicht mehr bei Microsoft ab. Der Schalter in den Ordneroptionen bleibt bedienbar.'] = 'The Explorer home page no longer shows recently used files from the Microsoft cloud (office.com, OneDrive); Windows no longer asks Microsoft for them. The switch in Folder Options stays usable.'
$t['Keine Benachrichtigungen im Sperrbildschirm'] = 'No notifications on the lock screen'
$t['Benachrichtigungen erscheinen nicht mehr auf dem Sperrbildschirm, wo sie jeder lesen kann, der vor dem Gerät steht.'] = 'Notifications no longer appear on the lock screen, where anyone standing in front of the device can read them.'
$t['Hintergrund-Apps verbieten'] = 'Forbid background apps'
$t['Store-Apps laufen nur, solange ihr Fenster offen ist: keine Hintergrund-Synchronisation, keine Live-Benachrichtigungen von Store-Apps. Desktop-Programme sind nicht betroffen.'] = 'Store apps only run while their window is open: no background sync, no live notifications from Store apps. Desktop programs are not affected.'
$t['Alle App-Benachrichtigungen abschalten'] = 'Turn off all app notifications'
$t['Keine App zeigt mehr Benachrichtigungen an - weder Pop-ups noch Einträge in der Mitteilungszentrale.'] = 'No app shows notifications any more - neither pop-ups nor entries in the notification centre.'
$t['Auch Windows-Sicherheit meldet einen Virenfund dann nicht mehr per Benachrichtigung; du siehst ihn nur noch in Windows-Sicherheit selbst und im Protokoll des Wächters.'] = 'Windows Security then no longer reports a detection by notification either; you only see it in Windows Security itself and in the watcher''s log.'
$t['Blickpunkt-Symbol auf dem Desktop ausblenden'] = 'Hide the Spotlight icon on the desktop'
$t['Blendet das Symbol "Weitere Informationen zu diesem Bild" aus, das Windows-Blickpunkt auf dem Desktop anlegt. Ohne Blickpunkt-Hintergrund ohne Wirkung.'] = 'Hides the "Learn more about this picture" icon that Windows Spotlight places on the desktop. No effect without a Spotlight background.'
$t['Windows-Tipps per Richtlinie abschalten'] = 'Turn off Windows tips by policy'
$t['Windows zeigt keine Tipps mehr an, die es anhand der Diagnosedaten auswählt.'] = 'Windows no longer shows tips that it selects based on diagnostic data.'
$t['Alle Blickpunkt-Funktionen abschalten'] = 'Turn off all Spotlight features'
$t['Schaltet Windows-Blickpunkt in einem Schritt ab: Bilder auf dem Sperrbildschirm, Tipps und Vorschläge für Microsoft-Angebote. Weniger Datenverkehr zu Microsoft.'] = 'Turns off Windows Spotlight in one step: lock screen pictures, tips and suggestions for Microsoft offers. Less traffic to Microsoft.'
$t['Auf dem Sperrbildschirm erscheinen danach keine wechselnden Blickpunkt-Bilder mehr.'] = 'The lock screen then no longer shows changing Spotlight pictures.'
$t['Keine App-Benachrichtigungen auf dem Sperrbildschirm'] = 'No app notifications on the lock screen'
$t['Auf dem gesperrten Bildschirm erscheinen keine Benachrichtigungen von Apps mehr - wer vor dem gesperrten Rechner sitzt, liest keine Nachrichten mit.'] = 'No more app notifications appear on the locked screen - anyone sitting in front of the locked PC cannot read along.'
$t['"App im Store suchen" bei unbekannten Dateien ausblenden'] = 'Hide "Look for an app in the Store" for unknown files'
$t['Beim Öffnen einer Datei ohne passendes Programm bietet Windows nicht mehr an, im Microsoft Store danach zu suchen.'] = 'When opening a file without a matching program, Windows no longer offers to search the Microsoft Store for one.'
$t['Häufig genutzte Apps nicht nachverfolgen'] = 'Do not track frequently used apps'
$t['Windows merkt sich nicht mehr, welche Apps du am häufigsten nutzt und suchst; Apps erscheinen in Suche und Auswahllisten alphabetisch.'] = 'Windows no longer remembers which apps you use and search most; apps appear alphabetically in search and selection lists.'
$t['Aufgabe "Abzüge online bestellen" entfernen'] = 'Remove the "Order prints online" task'
$t['Entfernt bei Bildern die Aufgabe, Abzüge online zu bestellen; der Assistent lädt dafür eine Anbieterliste aus dem Netz.'] = 'Removes the task to order prints online for pictures; the wizard downloads a list of providers for it.'
$t['Aufgabe "Im Web veröffentlichen" entfernen'] = 'Remove the "Publish to the web" task'
$t['Entfernt bei Dateien und Ordnern die Aufgabe, sie im Web zu veröffentlichen.'] = 'Removes the task to publish files and folders to the web.'
$t['Keine Anbieterlisten für Web-Assistenten laden'] = 'Do not download provider lists for web wizards'
$t['Die Assistenten zum Veröffentlichen im Web und zum Bestellen von Abzügen laden keine Anbieterlisten mehr aus dem Netz.'] = 'The wizards for publishing to the web and ordering prints no longer download provider lists from the internet.'
$t['Kamerazugriff für Apps'] = 'Camera access for apps'
$t['Sperrt den Kamerazugriff für Apps aus dem Microsoft Store. Klassische Desktop-Programme sind davon nicht betroffen und funktionieren weiter. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks camera access for apps from the Microsoft Store. Classic desktop programs are not affected and keep working. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Mikrofonzugriff für Apps'] = 'Microphone access for apps'
$t['Sperrt den Mikrofonzugriff für Apps aus dem Microsoft Store. Klassische Desktop-Programme bleiben unberührt. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks microphone access for apps from the Microsoft Store. Classic desktop programs are not affected. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Standortzugriff für Apps'] = 'Location access for apps'
$t['Sperrt den Zugriff auf deinen Standort für Apps aus dem Microsoft Store. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your location for apps from the Microsoft Store. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Kontaktzugriff für Apps'] = 'Contacts access for apps'
$t['Sperrt den Zugriff auf deine Kontakte. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your contacts. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Kalenderzugriff für Apps'] = 'Calendar access for apps'
$t['Sperrt den Zugriff auf deinen Kalender. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your calendar. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Anrufliste für Apps'] = 'Call history for apps'
$t['Sperrt den Zugriff auf die Anrufliste. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to the call history. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['E-Mail-Zugriff für Apps'] = 'Email access for apps'
$t['Sperrt den Zugriff auf deine E-Mails. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your emails. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Aufgabenzugriff für Apps'] = 'Tasks access for apps'
$t['Sperrt den Zugriff auf deine Aufgabenlisten. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your task lists. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Nachrichtenzugriff für Apps'] = 'Messaging access for apps'
$t['Sperrt den Zugriff auf SMS- und Chatnachrichten. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to SMS and chat messages. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Funkgeräte-Steuerung für Apps'] = 'Radio control for apps'
$t['Verhindert, dass Apps Bluetooth und WLAN selbsttätig ein- und ausschalten. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from switching Bluetooth and Wi-Fi on and off on their own. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Kopplung mit anderen Geräten'] = 'Communicate with unpaired devices'
$t['Verhindert, dass Apps Daten mit nicht gekoppelten Geräten in der Umgebung austauschen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from exchanging data with unpaired devices nearby. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Kontoinformationen für Apps'] = 'Account info for apps'
$t['Sperrt den Zugriff auf deinen Namen, dein Bild und andere Kontoangaben. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your name, picture and other account details. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['App-Diagnose für Apps'] = 'App diagnostics for apps'
$t['Verhindert, dass Apps Diagnoseinformationen über andere laufende Apps auslesen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from reading diagnostic information about other running apps. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Dokumentenordner für Apps'] = 'Documents folder for apps'
$t['Sperrt den Zugriff auf deinen Dokumentenordner für Store-Apps. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your Documents folder for Store apps. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bilderordner für Apps'] = 'Pictures folder for apps'
$t['Sperrt den Zugriff auf deinen Bilderordner für Store-Apps. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your Pictures folder for Store apps. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Videoordner für Apps'] = 'Videos folder for apps'
$t['Sperrt den Zugriff auf deinen Videoordner für Store-Apps. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your Videos folder for Store apps. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Generative KI für Apps'] = 'Generative AI for apps'
$t['Verhindert, dass Apps die in Windows eingebauten KI-Modelle nutzen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from using the AI models built into Windows. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Anwesenheitserkennung für Apps'] = 'Presence sensing for apps'
$t['Verhindert, dass Apps über einen Anwesenheitssensor erkennen, ob du vor dem Gerät sitzt. Ohne Sensor gibt es den Schalter nicht, dann wird nichts angelegt. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from using a presence sensor to detect whether you are sitting in front of the device. Without a sensor the switch does not exist and nothing is created. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Benachrichtigungen lesen'] = 'Read notifications'
$t['Verhindert, dass Apps deine Benachrichtigungen mitlesen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from reading your notifications. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bewegungsdaten für Apps'] = 'Motion data for apps'
$t['Sperrt den Zugriff auf Bewegungs- und Aktivitätsdaten (Schritte, Sitzen, Gehen). Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to motion and activity data (steps, sitting, walking). The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Telefonanrufe für Apps'] = 'Phone calls for apps'
$t['Verhindert, dass Apps Telefonanrufe führen oder verwalten. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from making or managing phone calls. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Mobilfunkdaten für Apps'] = 'Cellular data for apps'
$t['Sperrt den Zugriff auf die Mobilfunkverbindung. Ohne Mobilfunkmodem ohne Wirkung. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to the cellular connection. No effect without a cellular modem. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Augenverfolgung für Apps'] = 'Eye tracking for apps'
$t['Sperrt den Zugriff auf Geräte zur Augenverfolgung. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to eye tracking devices. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Downloadordner für Apps'] = 'Downloads folder for apps'
$t['Sperrt den Zugriff auf deinen Downloadordner für Store-Apps. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your Downloads folder for Store apps. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['WLAN-Informationen für Apps'] = 'Wi-Fi information for apps'
$t['Verhindert, dass Apps die Namen der WLANs in deiner Umgebung auslesen. Über WLAN-Namen lässt sich dein Standort bestimmen, auch wenn der Standortzugriff gesperrt ist. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Prevents apps from reading the names of Wi-Fi networks around you. Wi-Fi names can reveal your location even when location access is blocked. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Dateisystem für Apps'] = 'File system for apps'
$t['Store-Apps verlieren den Zugriff auf das gesamte Dateisystem und kommen nur noch an Dateien, die du selbst öffnest. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps lose access to the whole file system and only reach files you open yourself. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Musikordner für Apps'] = 'Music folder for apps'
$t['Sperrt den Zugriff auf deinen Musikordner für Store-Apps. Der Media Player zeigt deine Musik dann nicht mehr in seiner Bibliothek; einzelne Dateien spielt er weiter ab. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Blocks access to your Music folder for Store apps. Media Player then no longer shows your music in its library; it still plays individual files. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bildschirmaufnahme für Apps'] = 'Screen capture for apps'
$t['Store-Apps dürfen keine Fenster oder den Bildschirm aufnehmen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not capture windows or the screen. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Das Snipping Tool ist eine Store-App und kann danach keine Ausschnitte mehr aufnehmen.'] = 'The Snipping Tool is a Store app and can then no longer take snips.'
$t['Bildschirmaufnahme ohne Rahmen für Apps'] = 'Borderless screen capture for apps'
$t['Store-Apps dürfen keine Aufnahmen ohne den gelben Warnrahmen machen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not take captures without the yellow warning border. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Wie beim vorigen Punkt: betrifft auch das Snipping Tool.'] = 'As with the previous item: also affects the Snipping Tool.'
$t['Bildschirmaufnahme für Desktop-Programme'] = 'Screen capture for desktop programs'
$t['Auch klassische Desktop-Programme dürfen keine Fenster oder den Bildschirm über die Windows-Schnittstelle aufnehmen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Classic desktop programs may not capture windows or the screen through the Windows interface either. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bricht die Fensteraufnahme in OBS und die Bildschirmübertragung in Discord, Teams und ähnlichen Programmen.'] = 'Breaks window capture in OBS and screen sharing in Discord, Teams and similar programs.'
$t['Bildschirmaufnahme ohne Rahmen für Desktop-Programme'] = 'Borderless screen capture for desktop programs'
$t['Desktop-Programme dürfen keine Aufnahmen ohne Warnrahmen machen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Desktop programs may not take captures without the warning border. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Wie beim vorigen Punkt.'] = 'As with the previous item.'
$t['Passkeys für Apps'] = 'Passkeys for apps'
$t['Apps dürfen keine Passkeys verwenden. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Apps may not use passkeys. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Kann Passwortmanager abschneiden, die unter Windows als Passkey-Anbieter arbeiten.'] = 'Can cut off password managers that act as passkey providers in Windows.'
$t['Liste der Passkeys für Apps'] = 'Passkey list for apps'
$t['Apps dürfen die Liste deiner gespeicherten Passkeys nicht auslesen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Apps may not read the list of your stored passkeys. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bluetooth-Geräte für Apps'] = 'Bluetooth devices for apps'
$t['Store-Apps dürfen nicht mit gekoppelten Bluetooth-Geräten sprechen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not talk to paired Bluetooth devices. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bricht Store-Apps für Zubehör, etwa für Controller oder Kopfhörer.'] = 'Breaks Store apps for accessories, for example for controllers or headphones.'
$t['Eingabegeräte (HID) für Apps'] = 'Input devices (HID) for apps'
$t['Store-Apps dürfen nicht direkt auf Eingabegeräte zugreifen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not access input devices directly. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bricht Store-Apps, die Mäuse, Tastaturen oder Controller einstellen.'] = 'Breaks Store apps that configure mice, keyboards or controllers.'
$t['Eigene Sensoren für Apps'] = 'Custom sensors for apps'
$t['Store-Apps dürfen keine herstellereigenen Sensoren auslesen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not read vendor-specific sensors. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Serielle Schnittstellen für Apps'] = 'Serial ports for apps'
$t['Store-Apps dürfen nicht über serielle Schnittstellen kommunizieren. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not communicate via serial ports. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bricht Store-Apps für Mikrocontroller und Messgeräte.'] = 'Breaks Store apps for microcontrollers and measuring devices.'
$t['USB-Geräte für Apps'] = 'USB devices for apps'
$t['Store-Apps dürfen nicht direkt auf USB-Geräte zugreifen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not access USB devices directly. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['Bricht Store-Apps für Zubehör, das über USB eingestellt wird.'] = 'Breaks Store apps for accessories configured via USB.'
$t['Wi-Fi Direct für Apps'] = 'Wi-Fi Direct for apps'
$t['Store-Apps dürfen keine direkten WLAN-Verbindungen zu anderen Geräten aufbauen. Der Schalter in den Einstellungen bleibt bedienbar - du kannst die Berechtigung dort jederzeit wieder erteilen, und der Wächter setzt sie beim nächsten Start zurück.'] = 'Store apps may not establish direct Wi-Fi connections to other devices. The switch in Settings stays usable - you can grant the permission again there at any time, and the watcher resets it at the next start.'
$t['App-Diagnose: für alle Konten sperren'] = 'App diagnostics: block for all accounts'
$t['Schaltet den Zugriff auf App-Diagnose für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to app diagnostics for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Kalender: für alle Konten sperren'] = 'Calendar: block for all accounts'
$t['Schaltet den Zugriff auf Kalender für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to the calendar for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Bluetooth-Geräte: für alle Konten sperren'] = 'Bluetooth devices: block for all accounts'
$t['Schaltet den Zugriff auf Bluetooth-Geräte für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar. Programme, die darauf angewiesen sind, verlieren den Zugriff - bei Kamera und Mikrofon auch Desktop-Programme wie Discord oder Steam.'] = 'Turns off access to Bluetooth devices for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators. Programs that depend on it lose access - for camera and microphone also desktop programs such as Discord or Steam.'
$t['ungekoppelte Geräte: für alle Konten sperren'] = 'Unpaired devices: block for all accounts'
$t['Schaltet den Zugriff auf ungekoppelte Geräte für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to unpaired devices for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Dateisystem: für alle Konten sperren'] = 'File system: block for all accounts'
$t['Schaltet den Zugriff auf Dateisystem für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar. Programme, die darauf angewiesen sind, verlieren den Zugriff - bei Kamera und Mikrofon auch Desktop-Programme wie Discord oder Steam.'] = 'Turns off access to the file system for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators. Programs that depend on it lose access - for camera and microphone also desktop programs such as Discord or Steam.'
$t['Mobilfunkdaten: für alle Konten sperren'] = 'Cellular data: block for all accounts'
$t['Schaltet den Zugriff auf Mobilfunkdaten für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to cellular data for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Nachrichten: für alle Konten sperren'] = 'Messages: block for all accounts'
$t['Schaltet den Zugriff auf Nachrichten für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to messages for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Kontakte: für alle Konten sperren'] = 'Contacts: block for all accounts'
$t['Schaltet den Zugriff auf Kontakte für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to contacts for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Dokumente: für alle Konten sperren'] = 'Documents: block for all accounts'
$t['Schaltet den Zugriff auf Dokumente für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to documents for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Downloads: für alle Konten sperren'] = 'Downloads: block for all accounts'
$t['Schaltet den Zugriff auf Downloads für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to downloads for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['E-Mail: für alle Konten sperren'] = 'Email: block for all accounts'
$t['Schaltet den Zugriff auf E-Mail für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to email for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Augenverfolgung: für alle Konten sperren'] = 'Eye tracking: block for all accounts'
$t['Schaltet den Zugriff auf Augenverfolgung für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar.'] = 'Turns off access to eye tracking for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators.'
$t['Bildschirmaufnahme: für alle Konten sperren'] = 'Screen capture: block for all accounts'
$t['Schaltet den Zugriff auf Bildschirmaufnahme für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar. Programme, die darauf angewiesen sind, verlieren den Zugriff - bei Kamera und Mikrofon auch Desktop-Programme wie Discord oder Steam.'] = 'Turns off access to screen capture for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators. Programs that depend on it lose access - for camera and microphone also desktop programs such as Discord or Steam.'
$t['Bildschirmaufnahme ohne Rahmen: für alle Konten sperren'] = 'Borderless screen capture: block for all accounts'
$t['Schaltet den Zugriff auf Bildschirmaufnahme ohne Rahmen für alle Konten dieses Rechners ab (Hauptschalter oben auf der Datenschutzseite). Der Schalter bleibt für Administratoren bedienbar. Programme, die darauf angewiesen sind, verlieren den Zugriff - bei Kamera und Mikrofon auch Desktop-Programme wie Discord oder Steam.'] = 'Turns off access to borderless screen capture for all accounts on this PC (main switch at the top of the privacy page). The switch stays usable for administrators. Programs that depend on it lose access - for camera and microphone also desktop programs such as Discord or Steam.'
